  " · {0} crate{1} ready": " · gotowe skrzynie: {0}",
  "E — the {0} ({1}{2})": "E — {0} ({1}{2})",
  "solo": "sam",
  "Stand beside this gate's console on foot.": "Podejdź pieszo do konsoli tej bramy.",
  "Terminal locked for {0} seconds.": "Terminal zablokowany na {0} s.",
  "No connection.": "Brak połączenia.",
  "Connection open for {0} seconds. Both terminals are locked. Walk or drive through the ring.": "Połączenie otwarte na {0} s. Oba terminale są zablokowane. Przejdź lub przejedź przez pierścień.",
  "The destination exit is occupied. Wait for it to clear.": "Wyjście docelowe jest zajęte. Poczekaj, aż się zwolni.",
